/* Google Drive appDataFolder sync. Immutable change files avoid overwriting
   another device's unrelated edits. Access tokens exist only in memory. */
(function(){
'use strict';
const C=window.PMS,J=window.MoaJournal,CONFIG='moa.drive.config.v1',ACTIVE='moa.drive.active.v1',LOCAL='moa.personal-pms.v1',SCOPE='https://www.googleapis.com/auth/drive.appdata';
const clone=x=>JSON.parse(JSON.stringify(x));
let config=window.MOA_DRIVE_CONFIG||{},account=null,cache=null,token='',expires=0,client=null,busy=false,again=false,status='Google Drive 미연결',lastSync='',hooks=null,authLoading=null,paused=false,writable=!navigator.locks;
const uid=()=>crypto.randomUUID();
try{config={...config,...JSON.parse(localStorage.getItem(CONFIG)||'{}')};account=JSON.parse(localStorage.getItem(ACTIVE)||'null');if(account&&account.clientId!==config.clientId)account=null;if(account){cache=JSON.parse(localStorage.getItem(account.key));if(cache){cache.ops=J.merge([],cache.ops);C.validate(J.materialize(cache.ops));status='Google 재연결 필요';}else account=null;}}catch(_){account=null;cache=null;status='동기화 캐시 확인 필요';paused=true;}
function emit(message){if(message)status=message;hooks?.status(status);}
function persist(next){localStorage.setItem(account.key,JSON.stringify(next));cache=next;}
function current(){return C.validate(J.materialize(cache.ops));}
function save(next,previous){if(!writable)throw Error('다른 캘린더 탭을 닫고 이 탭을 새로고침해주세요.');if(!account||!cache){localStorage.setItem(LOCAL,JSON.stringify(next));return;}if(paused)throw Error('동기화 캐시를 먼저 확인해주세요.');const changes=J.diff(previous,next);if(!changes.length)return;const op={version:1,id:uid(),device:cache.device,clock:Math.max(0,...cache.ops.map(x=>x.clock))+1,createdAt:new Date().toISOString(),changes};persist({...cache,ops:J.merge(cache.ops,[op]),pending:[...cache.pending,op.id]});emit(navigator.onLine?'Drive 저장 대기':'오프라인 · 변경 보관 중');schedule();}
function initial(fallback){return account&&cache?current():fallback;}
function schedule(){if(token&&account){if(busy){again=true;return;}queueMicrotask(sync);}}
async function api(path,options={}){if(!token||Date.now()>=expires){token='';throw Error('Google 재연결 필요');}const r=await fetch('https://www.googleapis.com/'+path,{...options,headers:{Authorization:'Bearer '+token,...options.headers},signal:AbortSignal.timeout(30000)});if(r.status===401){token='';throw Error('Google 재연결 필요');}if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(r.status===403?'Drive 권한 또는 API 설정을 확인해주세요.':r.status===429?'요청이 많아 잠시 후 다시 시도합니다.':body.error?.message||'Drive 연결 오류 ('+r.status+')');}return r.json();}
async function pull(){let pageToken='',remote=[],known=new Set(cache.seen||[]),seen=[];do{const params=new URLSearchParams({spaces:'appDataFolder',pageSize:'1000',fields:'nextPageToken,files(id,name,size)',q:"trashed = false and appProperties has { key='moaJournal' and value='1' }"});if(pageToken)params.set('pageToken',pageToken);const list=await api('drive/v3/files?'+params);for(const f of list.files||[]){if(!known.has(f.id)){if(Number(f.size)>8*1024*1024)throw Error('동기화 파일 크기를 확인해주세요.');remote.push(J.check(await api('drive/v3/files/'+encodeURIComponent(f.id)+'?alt=media')));}seen.push(f.id);}pageToken=list.nextPageToken||'';}while(pageToken);
 // Read the latest local cache after network awaits, preserving edits made in flight.
 const ops=J.merge(cache.ops,remote);C.validate(J.materialize(ops));const remoteIds=new Set(remote.map(x=>x.id));persist({...cache,ops,seen:[...new Set([...(cache.seen||[]),...seen])],pending:cache.pending.filter(id=>!remoteIds.has(id))});hooks.replace(current());}
async function upload(op){const boundary='moa_'+uid().replace(/-/g,'');const meta={name:'moa-change-'+op.id+'.json',mimeType:'application/json',parents:['appDataFolder'],appProperties:{moaJournal:'1'}};const body='--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify(meta)+'\r\n--'+boundary+'\r\nContent-Type: application/json\r\n\r\n'+JSON.stringify(op)+'\r\n--'+boundary+'--';return api('upload/drive/v3/files?uploadType=multipart&fields=id',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body});}
async function sync(){if(busy){again=true;return;}if(!account||!cache||paused||!writable)return;if(!navigator.onLine){emit('오프라인 · 변경 보관 중');return;}if(!token||Date.now()>=expires){emit('Google 재연결 필요');return;}busy=true;try{emit('Drive 동기화 중');await pull();for(const id of [...cache.pending]){const op=cache.ops.find(x=>x.id===id);if(!op)throw Error('대기 중인 변경 기록을 확인해주세요.');const file=await upload(op);persist({...cache,pending:cache.pending.filter(x=>x!==id),seen:[...new Set([...(cache.seen||[]),file.id])]});}await pull();lastSync=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});emit(cache.pending.length?'Drive 저장 대기':'Drive 동기화 완료 · '+lastSync);}catch(e){emit(e.message||'동기화 실패 · 변경은 기기에 보관');}finally{busy=false;if(again){again=false;schedule();}}}
function loadGIS(){if(window.google?.accounts?.oauth2)return Promise.resolve();if(authLoading)return authLoading;authLoading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=()=>resolve();s.onerror=()=>{authLoading=null;s.remove();reject(Error('Google 로그인 모듈을 불러오지 못했습니다.'));};document.head.append(s);});return authLoading;}
async function ready(){if(!config.clientId)return;await loadGIS();client=google.accounts.oauth2.initTokenClient({client_id:config.clientId,scope:SCOPE,include_granted_scopes:false,callback:authorized,error_callback:()=>emit('로그인 창이 닫혔습니다. 다시 연결해주세요.')});}
async function authorized(response){if(response.error){emit('Google 연결을 허용하지 않았습니다.');return;}token=response.access_token;expires=Date.now()+Number(response.expires_in)*1000-60000;try{const about=await api('drive/v3/about?fields=user(permissionId,emailAddress)');const user=about.user;if(!user?.permissionId)throw Error('Google 계정을 확인하지 못했습니다.');const nextAccount={id:user.permissionId,email:user.emailAddress||'Google 계정',clientId:config.clientId,key:'moa.drive.cache.v1:'+config.clientId+':'+user.permissionId};let nextCache=JSON.parse(localStorage.getItem(nextAccount.key)||'null');if(!nextCache)nextCache={version:1,device:uid(),ops:[],pending:[],seen:[]};nextCache.ops=J.merge([],nextCache.ops);C.validate(J.materialize(nextCache.ops));localStorage.setItem(ACTIVE,JSON.stringify(nextAccount));account=nextAccount;cache=nextCache;persist(cache);paused=false;hooks.replace(current());hooks.account?.();emit('Drive 연결됨');await sync();}catch(e){token='';emit(e.message);}}
function connect(){if(!writable){emit('다른 캘린더 탭을 닫고 새로고침해주세요.');return;}if(!config.clientId){hooks.open();return;}if(!client){emit('로그인 모듈 준비 중 · 잠시 후 연결해주세요.');ready().catch(e=>emit(e.message));return;}if(busy){emit('동기화가 끝난 뒤 계정을 연결해주세요.');return;}client.requestAccessToken({prompt:account?'':'select_account'});}
function configure(clientId){if(!writable)throw Error('다른 캘린더 탭을 닫고 새로고침해주세요.');if(!/^\d+-[a-zA-Z0-9-]+\.apps\.googleusercontent\.com$/.test(clientId))throw Error('올바른 Google OAuth 클라이언트 ID를 입력해주세요.');if(busy)throw Error('동기화가 끝난 뒤 설정해주세요.');if(account&&config.clientId!==clientId)throw Error('먼저 연결을 해제한 후 다른 클라이언트 ID를 설정해주세요.');localStorage.setItem(CONFIG,JSON.stringify({clientId}));config={clientId};client=null;emit('Google 연결 버튼을 눌러주세요.');return ready();}
function disconnect(){if(!writable)throw Error('다른 캘린더 탭에서 연결을 관리해주세요.');if(busy)throw Error('동기화가 끝난 뒤 연결을 해제해주세요.');localStorage.removeItem(ACTIVE);token='';expires=0;account=null;cache=null;hooks.replace(C.validate(JSON.parse(localStorage.getItem(LOCAL)||JSON.stringify(C.blank()))));emit('Google Drive 미연결');}
function importLocal(){if(!account)throw Error('Google Drive에 먼저 연결해주세요.');const local=C.validate(JSON.parse(localStorage.getItem(LOCAL)||JSON.stringify(C.blank()))),before=current(),next=clone(before);for(const k of ['projects','tasks','events'])for(const x of local[k]){const at=next[k].findIndex(y=>y.id===x.id);if(at<0)next[k].push(x);else next[k][at]=x;}C.validate(next);save(next,before);hooks.replace(current());}
window.MoaDrive={init(h){hooks=h;if(navigator.locks)navigator.locks.request('moa-drive-writer',{ifAvailable:true},async lock=>{writable=!!lock;if(!lock){emit('다른 캘린더 탭 사용 중 · 이 탭은 읽기 전용');return;}await new Promise(()=>{});}).catch(()=>emit('저장 권한 확인 실패 · 새로고침 필요'));emit();if(config.clientId)ready().catch(e=>emit(e.message));},initial,save,sync,connect,configure,disconnect,importLocal,info:()=>({status,clientId:config.clientId||'',account:account?.email||'',pending:cache?.pending.length||0,connected:!!token&&Date.now()<expires,lastSync})};
window.addEventListener('online',schedule);window.addEventListener('focus',()=>{if(!document.hidden)schedule();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedule();});setInterval(()=>{if(!document.hidden)schedule();},30000);
// Another tab can edit the same account cache. Reload it before syncing/rendering.
window.addEventListener('storage',e=>{if(account&&e.key===account.key&&e.newValue){try{const incoming=JSON.parse(e.newValue);incoming.ops=J.merge([],incoming.ops);cache=incoming;hooks?.replace(current());schedule();}catch(_){paused=true;emit('다른 탭의 동기화 데이터를 확인해주세요.');}}if(e.key===ACTIVE&&e.newValue!==JSON.stringify(account)){token='';paused=true;emit('다른 탭에서 계정 변경 · 새로고침 필요');}});
})();
